"use client"

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { useState, type ReactNode } from "react"

import { cn } from "@/lib/utils"

/**
 * Props for the checkbox root (`checked`, `indeterminate`, `name`, …).
 */
type CheckboxProps = CheckboxPrimitive.Root.Props

/**
 * Accessible checkbox control. Pair with Field or a wrapping label.
 *
 * After the first toggle, the check / indeterminate mark runs a morph animation.
 * Honors `prefers-reduced-motion`.
 */
const Checkbox = ({ className, onCheckedChange, ...props }: CheckboxProps) => {
  const [morph, setMorph] = useState(false)

  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      data-morph={morph ? "" : undefined}
      className={cn(
        "group/checkbox peer inline-flex size-4 shrink-0 items-center justify-center rounded-[4px] border border-input bg-transparent text-primary-foreground shadow-none outline-none",
        "transition-colors duration-200 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none",
        "focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "data-checked:border-primary data-checked:bg-primary",
        "data-indeterminate:border-primary data-indeterminate:bg-primary",
        "disabled:cursor-not-allowed disabled:opacity-50",
        "aria-invalid:border-destructive aria-invalid:ring-2 aria-invalid:ring-destructive/30",
        "data-invalid:border-destructive data-invalid:ring-2 data-invalid:ring-destructive/30",
        "data-valid:border-success data-valid:ring-2 data-valid:ring-success/30",
        className
      )}
      onCheckedChange={(checked, eventDetails) => {
        setMorph(true)
        onCheckedChange?.(checked, eventDetails)
      }}
      {...props}
    />
  )
}

type CheckboxIndicatorProps = CheckboxPrimitive.Indicator.Props & {
  readonly children?: ReactNode
}

/**
 * Default check mark — stroke path morphs on toggle when the root has `data-morph`.
 */
const CheckboxCheckMark = () => (
  <svg
    viewBox="0 0 14 14"
    fill="none"
    aria-hidden="true"
    className="size-3.5 in-data-indeterminate:hidden"
  >
    <path
      data-slot="checkbox-check"
      d="M3 7.2 5.8 10l5.2-6"
      pathLength={1}
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
)

/**
 * Default indeterminate mark — stretches on toggle when the root has `data-morph`.
 */
const CheckboxIndeterminateMark = () => (
  <svg
    viewBox="0 0 14 14"
    fill="none"
    aria-hidden="true"
    className="size-3.5 hidden in-data-indeterminate:block"
  >
    <path
      data-slot="checkbox-indeterminate"
      d="M3 7h8"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
    />
  </svg>
)

/**
 * Check / indeterminate mark inside the checkbox.
 * Enter/exit morph runs after the parent Checkbox’s first state change (`data-morph`).
 */
const CheckboxIndicator = ({
  className,
  children,
  ...props
}: CheckboxIndicatorProps) => {
  return (
    <CheckboxPrimitive.Indicator
      data-slot="checkbox-indicator"
      className={cn("flex items-center justify-center text-current", className)}
      {...props}
    >
      {children ?? (
        <>
          <CheckboxCheckMark />
          <CheckboxIndeterminateMark />
        </>
      )}
    </CheckboxPrimitive.Indicator>
  )
}

export { Checkbox, CheckboxIndicator }
export type { CheckboxIndicatorProps, CheckboxProps }

/*
 * Checkbox checkmark morph keyframes for @nk/checkbox.
 * Stroke draws with a mid-motion overshoot (same spirit as Switch thumb morph).
 * Imported by the docs site (app/globals.css) and published via the registry.
 */

@theme inline {
  --animate-nk-checkbox-check-on: nk-checkbox-check-on 320ms
    cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-nk-checkbox-check-off: nk-checkbox-check-off 240ms
    cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-nk-checkbox-indeterminate-on: nk-checkbox-indeterminate-on 280ms
    cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-nk-checkbox-indeterminate-off: nk-checkbox-indeterminate-off 200ms
    cubic-bezier(0.22, 1, 0.36, 1) both;

  @keyframes nk-checkbox-check-on {
    0% {
      stroke-dashoffset: 1;
      opacity: 0;
      transform: scale(0.55);
    }
    45% {
      stroke-dashoffset: 0.12;
      opacity: 1;
      transform: scale(1.22);
    }
    100% {
      stroke-dashoffset: 0;
      opacity: 1;
      transform: scale(1);
    }
  }

  @keyframes nk-checkbox-check-off {
    0% {
      stroke-dashoffset: 0;
      opacity: 1;
      transform: scale(1);
    }
    45% {
      stroke-dashoffset: 0.2;
      opacity: 1;
      transform: scale(1.18);
    }
    100% {
      stroke-dashoffset: 1;
      opacity: 0;
      transform: scale(0.55);
    }
  }

  @keyframes nk-checkbox-indeterminate-on {
    0% {
      opacity: 0;
      transform: scaleX(0.2);
    }
    45% {
      opacity: 1;
      transform: scaleX(1.28);
    }
    100% {
      opacity: 1;
      transform: scaleX(1);
    }
  }

  @keyframes nk-checkbox-indeterminate-off {
    0% {
      opacity: 1;
      transform: scaleX(1);
    }
    100% {
      opacity: 0;
      transform: scaleX(0.2);
    }
  }
}

/* Morph only after the first user toggle (`data-morph` on the checkbox root). */
@media (prefers-reduced-motion: no-preference) {
  [data-slot="checkbox"][data-morph] [data-slot="checkbox-check"] {
    stroke-dasharray: 1;
    transform-box: fill-box;
    transform-origin: center;
  }

  [data-slot="checkbox"][data-morph]
    [data-slot="checkbox-indicator"][data-starting-style]
    [data-slot="checkbox-check"] {
    animation: var(--animate-nk-checkbox-check-on);
  }

  [data-slot="checkbox"][data-morph]
    [data-slot="checkbox-indicator"][data-ending-style]
    [data-slot="checkbox-check"] {
    animation: var(--animate-nk-checkbox-check-off);
  }

  [data-slot="checkbox"][data-morph] [data-slot="checkbox-indeterminate"] {
    transform-box: fill-box;
    transform-origin: center;
  }

  [data-slot="checkbox"][data-morph]
    [data-slot="checkbox-indicator"][data-starting-style]
    [data-slot="checkbox-indeterminate"] {
    animation: var(--animate-nk-checkbox-indeterminate-on);
  }

  [data-slot="checkbox"][data-morph]
    [data-slot="checkbox-indicator"][data-ending-style]
    [data-slot="checkbox-indeterminate"] {
    animation: var(--animate-nk-checkbox-indeterminate-off);
  }
}
